urlset:
{%- for entry in entries %}

  {{ entry.permalink | escape_xml | safe }}
  {%- if entry.updated %}{{ entry.updated }}{% endif %}

{%- endfor %}
{#- Read mdBook's existing chapter list instead of maintaining a second one. #}
{%- set summary = load_data(path=".docs/SUMMARY.md", format="plain") %}
{%- for line in summary | split(pat="\n") %}
  {%- if ".md)" in line %}
    {%- set chapter = line | regex_replace(pattern=".*\\]\\(([^)]+\\.md)\\).*", rep="$1") %}
    {%- set content = load_data(path=".docs/" ~ chapter, format="plain") %}
    {%- if content | trim %}
      {%- if chapter == "book.md" %}
        {%- set url = get_url(path="docs/", trailing_slash=true) %}
      {%- else %}
        {%- set url = get_url(path="docs/" ~ chapter | replace(from=".md", to=".html")) %}
      {%- endif %}
{{ url | escape_xml | safe }}
    {%- endif %}
  {%- endif %}
{%- endfor %}
